//! 导出输出的独占暂存和原子无覆盖发布。只操作 activeRoot/modpacks 下本任务拥有的节点。
use super::{access::{leaf, linked, Directory}, Result};
use std::{fs::{self, File, Metadata, OpenOptions}, io, path::{Path, PathBuf}};
fn io_error(_:io::Error)->String{"整合包输出文件操作失败".into()}
fn conflict()->String{"导出目标已存在；为保留原整合包，本次导出未覆盖，请先移动或删除原文件".into()}
#[derive(Clone,PartialEq,Eq)] struct Identity(u64,u64);
#[cfg(unix)] fn identity(_: &File,meta:&Metadata)->Result<Identity>{use std::os::unix::fs::MetadataExt;Ok(Identity(meta.dev(),meta.ino()))}
#[cfg(windows)] fn identity(file:&File,_:&Metadata)->Result<Identity>{use std::{ffi::c_void,os::windows::io::AsRawHandle};#[repr(C)]struct Info{attributes:u32,created:[u32;2],accessed:[u32;2],modified:[u32;2],volume:u32,hi:u32,lo:u32,links:u32,index_hi:u32,index_lo:u32}#[link(name="kernel32")]extern "system"{fn GetFileInformationByHandle(file:*mut c_void,info:*mut Info)->i32;}let mut info:Info=unsafe{std::mem::zeroed()};if unsafe{GetFileInformationByHandle(file.as_raw_handle(),&mut info)}==0{return Err("无法确认导出暂存身份".into());}if !file.metadata().map_err(io_error)?.is_dir()&&info.links!=1{return Err("拒绝多硬链接导出暂存".into());}Ok(Identity(info.volume as u64,(info.index_hi as u64)<<32|info.index_lo as u64))}
#[cfg(not(any(unix,windows)))] fn identity(_:&File,_:&Metadata)->Result<Identity>{Err("当前平台无法安全发布整合包".into())}
fn file_identity(file:&File,published:bool)->Result<Identity>{let meta=file.metadata().map_err(io_error)?;if linked(&meta)||!meta.is_file(){return Err("导出暂存不是普通文件".into());}#[cfg(unix)]{use std::os::unix::fs::MetadataExt;let limit=if published{2}else{1};if meta.nlink()==0||meta.nlink()>limit{return Err("导出暂存存在未确认硬链接".into());}}#[cfg(not(unix))]let _=published;identity(file,&meta)}

pub(super) struct Stage {parent:Directory,target:String,name:String,directory:Option<Directory>,created:bool,file:Option<File>,anchor:Option<File>,identity:Option<Identity>,moved:bool,published:bool,payload_created:bool}
impl Stage {
    // 这里只建立/验证固定输出目录，随机暂存的所有变更从 initialize 开始且先被 caller 持有。
    pub(super) fn new(root:&Directory,target:&str)->Result<Self>{leaf(target)?;root.verify()?;let root=root.clone();let node=match root.child("modpacks")?{Some(node)=>node,None=>{root.verify()?;match native::mkdir(root.handle(),root.path(),"modpacks"){Ok(())=>{},Err(e) if e.kind()==io::ErrorKind::AlreadyExists=>{},Err(e)=>return Err(io_error(e))}root.verify()?;root.child("modpacks")?.ok_or("导出目录建立后无法确认")?}};let parent=root.directory(node)?;native::absent(parent.handle(),parent.path(),target)?;Ok(Self{parent,target:target.into(),name:format!(".hcmcl-pack-export-{}",uuid::Uuid::new_v4()),directory:None,created:false,file:None,anchor:None,identity:None,moved:false,published:false,payload_created:false})}
    pub(super) fn initialize(&mut self)->Result<()>{self.parent.verify()?;native::mkdir(self.parent.handle(),self.parent.path(),&self.name).map_err(io_error)?;self.created=true;let node=self.parent.child(&self.name)?.ok_or("暂存目录建立后已改变")?;self.directory=Some(self.parent.directory(node)?);let dir=self.directory.as_ref().ok_or("暂存目录未打开")?;let file=native::new_file(dir.handle(),dir.path(),"payload")?;self.payload_created=true;self.identity=Some(file_identity(&file,false)?);self.file=Some(file);self.anchor=Some(self.file.as_ref().ok_or("暂存文件未打开")?.try_clone().map_err(io_error)?);self.parent.verify()?;Ok(())}
    pub(super) fn take_file(&mut self)->Result<File>{self.file.take().ok_or_else(||"整合包暂存文件已消费".into())}
    fn verify_file(&self)->Result<()>{self.parent.verify()?;let dir=self.directory.as_ref().ok_or("整合包暂存目录不可用")?;dir.verify()?;let anchor=self.anchor.as_ref().ok_or("整合包暂存身份不可用")?;let expected=self.identity.as_ref().ok_or("整合包暂存身份未确认")?;if &file_identity(anchor,self.published)?!=expected{return Err("整合包暂存句柄身份改变".into());}let current=native::existing(dir.handle(),dir.path(),"payload")?;if &file_identity(&current,self.published)?!=expected{return Err("整合包暂存路径身份改变".into());}Ok(())}
    pub(super) fn validate(&self,cancel:&crate::downloads::Cancel)->Result<()> {cancel.check()?;self.verify_file()?;let dir=self.directory.as_ref().ok_or("暂存目录不可用")?;let mut file=native::existing(dir.handle(),dir.path(),"payload")?;super::parser::probe(&mut file,Path::new(&self.target)).map_err(|e|format!("导出 ZIP 不符合当前本地 reader 安全预算，未发布：{e}"))?;cancel.check()?;self.verify_file()}
    pub(super) fn publish(&mut self)->Result<PathBuf>{self.verify_file()?;let dir=self.directory.as_ref().ok_or("暂存目录不可用")?;let anchor=self.anchor.as_ref().ok_or("暂存文件不可用")?;native::absent(self.parent.handle(),self.parent.path(),&self.target)?;self.moved=native::publish(anchor,dir.handle(),dir.path(),self.parent.handle(),self.parent.path(),&self.target)?;self.published=true;Ok(self.parent.path().join(&self.target))}
    pub(super) fn cleanup(&mut self)->Result<()>{
        self.file.take();if !self.created{return Ok(());}let dir=self.directory.as_ref().ok_or("暂存目录身份未确认，拒绝按名称清理")?;dir.verify()?;
        if self.payload_created&&!self.moved{self.verify_file()?;self.anchor.take();native::unlink(dir.handle(),dir.path(),"payload",false)?;self.payload_created=false;}else{self.anchor.take();}
        let mut budget=8;let names=dir.names(&mut budget)?;if !names.is_empty(){return Err("暂存目录存在未确认内容，拒绝删除".into());}dir.verify()?;self.directory.take();self.parent.verify()?;native::unlink(self.parent.handle(),self.parent.path(),&self.name,true)?;self.created=false;Ok(())
    }
}

#[cfg(unix)] mod native {
    use super::*;use std::{ffi::CString,os::{fd::{AsRawFd,FromRawFd},unix::fs::OpenOptionsExt}};
    #[cfg(any(target_os="macos",target_os="ios"))]const NOFOLLOW:i32=0x100;
    #[cfg(all(target_os="android",any(target_arch="arm",target_arch="aarch64")))]const NOFOLLOW:i32=0x8000;
    #[cfg(not(any(target_os="macos",target_os="ios",all(target_os="android",any(target_arch="arm",target_arch="aarch64")))))]const NOFOLLOW:i32=0x20000;
    #[cfg(any(target_os="macos",target_os="ios"))]const CLOEXEC:i32=0x1000000;
    #[cfg(not(any(target_os="macos",target_os="ios")))]const CLOEXEC:i32=0x80000;
    #[cfg(any(target_os="macos",target_os="ios"))]const NONBLOCK:i32=4;
    #[cfg(not(any(target_os="macos",target_os="ios")))]const NONBLOCK:i32=0x800;
    #[cfg(any(target_os="macos",target_os="ios"))]const CREATE_EXCL:i32=0x200|0x800;
    #[cfg(not(any(target_os="macos",target_os="ios")))]const CREATE_EXCL:i32=0x40|0x80;
    extern "C"{fn openat(fd:i32,name:*const std::os::raw::c_char,flags:i32,...)->i32;fn mkdirat(fd:i32,name:*const std::os::raw::c_char,mode:u32)->i32;fn unlinkat(fd:i32,name:*const std::os::raw::c_char,flags:i32)->i32;}
    fn name(value:&str)->Result<CString>{CString::new(leaf(value)?).map_err(|_|"输出名称无效".into())}
    pub(super) fn mkdir(parent:&File,_:&Path,value:&str)->io::Result<()>{let name=CString::new(value).map_err(|_|io::Error::from(io::ErrorKind::InvalidInput))?;if unsafe{mkdirat(parent.as_raw_fd(),name.as_ptr(),0o700)}<0{Err(io::Error::last_os_error())}else{Ok(())}}
    pub(super) fn new_file(parent:&File,_:&Path,value:&str)->Result<File>{let n=name(value)?;let fd=unsafe{openat(parent.as_raw_fd(),n.as_ptr(),2|CREATE_EXCL|NOFOLLOW|CLOEXEC,0o600u32)};if fd<0{Err(io_error(io::Error::last_os_error()))}else{Ok(unsafe{File::from_raw_fd(fd)})}}
    pub(super) fn existing(parent:&File,_:&Path,value:&str)->Result<File>{let n=name(value)?;let fd=unsafe{openat(parent.as_raw_fd(),n.as_ptr(),NOFOLLOW|CLOEXEC|NONBLOCK)};if fd<0{Err(io_error(io::Error::last_os_error()))}else{Ok(unsafe{File::from_raw_fd(fd)})}}
    pub(super) fn absent(parent:&File,path:&Path,value:&str)->Result<()>{match existing(parent,path,value){Ok(_)=>Err(conflict()),Err(_)=>{let n=name(value)?;let fd=unsafe{openat(parent.as_raw_fd(),n.as_ptr(),NOFOLLOW|CLOEXEC|NONBLOCK)};if fd>=0{drop(unsafe{File::from_raw_fd(fd)});return Err(conflict());}let error=io::Error::last_os_error();if error.kind()==io::ErrorKind::NotFound{Ok(())}else{Err(conflict())}}}}
    pub(super) fn unlink(parent:&File,_:&Path,value:&str,directory:bool)->Result<()>{let n=name(value)?;#[cfg(any(target_os="macos",target_os="ios"))]let remove_dir=0x80;#[cfg(not(any(target_os="macos",target_os="ios")))]let remove_dir=0x200;if unsafe{unlinkat(parent.as_raw_fd(),n.as_ptr(),if directory{remove_dir}else{0})}<0{Err(io_error(io::Error::last_os_error()))}else{Ok(())}}
    pub(super) fn publish(source:&File,_:&File,_:&Path,to:&File,_:&Path,target:&str)->Result<bool>{let target=name(target)?;
        #[cfg(any(target_os="linux",target_os="android"))]{extern "C"{fn linkat(olddir:i32,old:*const std::os::raw::c_char,newdir:i32,new:*const std::os::raw::c_char,flags:i32)->i32;}let path=CString::new(format!("/proc/self/fd/{}",source.as_raw_fd())).map_err(|_|"暂存 FD 无效")?;if unsafe{linkat(-100,path.as_ptr(),to.as_raw_fd(),target.as_ptr(),0x400)}<0{let error=io::Error::last_os_error();return Err(if error.kind()==io::ErrorKind::AlreadyExists{conflict()}else{io_error(error)});}Ok(false)}
        #[cfg(any(target_os="macos",target_os="ios"))]{extern "C"{fn fclonefileat(source:i32,dest:i32,path:*const std::os::raw::c_char,flags:u32)->i32;}if unsafe{fclonefileat(source.as_raw_fd(),to.as_raw_fd(),target.as_ptr(),0)}<0{let error=io::Error::last_os_error();return Err(if error.kind()==io::ErrorKind::AlreadyExists{conflict()}else{io_error(error)});}Ok(false)}
        #[cfg(not(any(target_os="linux",target_os="android",target_os="macos",target_os="ios")))]{let _=(source,to,target);Err("当前平台不支持原子无覆盖发布".into())}
    }
}
#[cfg(windows)] mod native {
    use super::*;use std::os::windows::fs::OpenOptionsExt;
    pub(super) fn mkdir(_:&File,parent:&Path,name:&str)->io::Result<()>{fs::create_dir(parent.join(name))}
    pub(super) fn new_file(_:&File,parent:&Path,name:&str)->Result<File>{OpenOptions::new().write(true).create_new(true).access_mode(0x40000000|0x10000).share_mode(1).custom_flags(0x00200000).open(parent.join(leaf(name)?)).map_err(io_error)}
    pub(super) fn existing(_:&File,parent:&Path,name:&str)->Result<File>{OpenOptions::new().read(true).share_mode(7).custom_flags(0x00200000).open(parent.join(leaf(name)?)).map_err(io_error)}
    pub(super) fn absent(_:&File,parent:&Path,name:&str)->Result<()>{match fs::symlink_metadata(parent.join(leaf(name)?)){Err(e)if e.kind()==io::ErrorKind::NotFound=>Ok(()),_=>Err(conflict())}}
    pub(super) fn unlink(_:&File,parent:&Path,name:&str,directory:bool)->Result<()>{if directory{fs::remove_dir(parent.join(leaf(name)?))}else{fs::remove_file(parent.join(leaf(name)?))}.map_err(io_error)}
    pub(super) fn publish(source:&File,_:&File,_:&Path,_:&File,to:&Path,target:&str)->Result<bool>{use std::{ffi::c_void,os::windows::{ffi::OsStrExt,io::AsRawHandle}};#[repr(C)]struct RenameInfo{replace:u8,root:*mut c_void,length:u32,name:[u16;1]}#[link(name="kernel32")]extern "system"{fn SetFileInformationByHandle(file:*mut c_void,class:i32,info:*mut c_void,size:u32)->i32;}
        let path=to.join(leaf(target)?);let wide=path.as_os_str().encode_wide().collect::<Vec<_>>();let offset=std::mem::offset_of!(RenameInfo,name);let size=offset.checked_add(wide.len().checked_mul(2).ok_or("输出路径过长")?).ok_or("输出路径过长")?.max(std::mem::size_of::<RenameInfo>());let mut buffer=vec![0usize;(size+std::mem::size_of::<usize>()-1)/std::mem::size_of::<usize>()];let info=buffer.as_mut_ptr().cast::<RenameInfo>();unsafe{(*info).replace=0;(*info).root=std::ptr::null_mut();(*info).length=(wide.len()*2)as u32;std::ptr::copy_nonoverlapping(wide.as_ptr(),buffer.as_mut_ptr().cast::<u8>().add(offset).cast::<u16>(),wide.len());}if unsafe{SetFileInformationByHandle(source.as_raw_handle(),3,info.cast(),size as u32)}==0{let error=io::Error::last_os_error();return Err(if matches!(error.raw_os_error(),Some(80|183)){conflict()}else{io_error(error)});}Ok(true)
    }
}
#[cfg(test)]mod tests{
    use super::*;use std::io::Write;
    struct Fixture(PathBuf);impl Fixture{fn new()->Self{let p=std::env::temp_dir().join(format!("hcmcl-pack-output-{}",uuid::Uuid::new_v4()));fs::create_dir(&p).unwrap();Self(fs::canonicalize(p).unwrap())}}impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
    fn stage(root:&Path,name:&str)->Stage{let root=Directory::open(root).unwrap();let mut stage=Stage::new(&root,name).unwrap();stage.initialize().unwrap();let mut file=stage.take_file().unwrap();file.write_all(b"fixture archive").unwrap();file.sync_all().unwrap();drop(file);stage}
    #[test]fn native_no_replace_preserves_original_and_concurrent_winner(){let f=Fixture::new();let mut first=stage(&f.0,"中文.zip");let path=first.publish().unwrap();first.cleanup().unwrap();assert_eq!(fs::read(&path).unwrap(),b"fixture archive");drop(first);assert!(Stage::new(&Directory::open(&f.0).unwrap(),"中文.zip").is_err());let mut second=stage(&f.0,"winner.zip");fs::write(f.0.join("modpacks/winner.zip"),b"winner").unwrap();assert!(second.publish().unwrap_err().contains("已存在"));second.cleanup().unwrap();assert_eq!(fs::read(f.0.join("modpacks/winner.zip")).unwrap(),b"winner");assert_eq!(fs::read_dir(f.0.join("modpacks")).unwrap().count(),2);}
    #[test]fn uncommitted_cleanup_removes_only_owned_payload_and_unknown_children_survive(){let f=Fixture::new();let mut stage=stage(&f.0,"cancelled.zip");let private=stage.directory.as_ref().unwrap().path().to_path_buf();fs::write(private.join("unknown"),b"keep").unwrap();assert!(stage.cleanup().is_err());assert!(!f.0.join("modpacks/cancelled.zip").exists());assert_eq!(fs::read(private.join("unknown")).unwrap(),b"keep");drop(stage);}
    #[test]fn initialization_cleanup_and_invalid_targets_are_bounded(){let f=Fixture::new();let root=Directory::open(&f.0).unwrap();for name in ["../x","CON.zip","bad.","a:b.zip"]{assert!(Stage::new(&root,name).is_err());}let mut s=Stage::new(&root,"cancel.zip").unwrap();s.initialize().unwrap();s.cleanup().unwrap();assert_eq!(fs::read_dir(f.0.join("modpacks")).unwrap().count(),0);}
    #[cfg(unix)]#[test]fn changed_output_parent_is_detected_and_never_writes_replacement(){let f=Fixture::new();let mut s=stage(&f.0,"demo.zip");fs::rename(f.0.join("modpacks"),f.0.join("moved")).unwrap();fs::create_dir(f.0.join("modpacks")).unwrap();assert!(s.publish().is_err());assert!(s.cleanup().is_err());assert!(!f.0.join("modpacks/demo.zip").exists());drop(s);}
}
